package com.autoops.execution.executor;import com.autoops.infrastructure.remote.RemoteClient;import com.autoops.workflow.entity.WaitUntilStep;import org.springframework.stereotype.Component;@Component public class WaitUntilStepExecutor implements StepExecutor<WaitUntilStep>{private final RemoteClient remote;public WaitUntilStepExecutor(RemoteClient r){remote=r;}public Class<WaitUntilStep> supports(){return WaitUntilStep.class;}public StepResult execute(WaitUntilStep s,ExecutionContext c){long end=System.currentTimeMillis()+s.timeoutSeconds()*1000L;StepResult last=new StepResult(false,"","timeout",-1);while(System.currentTimeMillis()<end){var r=remote.execute(c.host(),c.port(),c.username(),c.password(),s.checkCommand(),Math.min(30,s.timeoutSeconds()));boolean ok=s.matches(r.exitCode(),r.stdout());last=new StepResult(ok,r.stdout(),r.stderr(),r.exitCode());if(ok)return last;try{Thread.sleep(s.intervalSeconds()*1000L);}catch(InterruptedException e){Thread.currentThread().interrupt();return new StepResult(false,"","cancelled",-1);}}return last;}}
